<div class="marketplace-grid"><section class="panel customer-form-panel"><h3>Üretim reçetesi</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="recipe"><label>Reçete adı<input name="name" required></label><label>Üretilecek ürün<select name="output_product_id" required><?php foreach($products as $p): ?><option value="<?= (int)$p['id'] ?>"><?= kd_e($p['name']) ?></option><?php endforeach; ?></select></label><label>Parti çıktısı (adet)<input type="number" name="batch_size" min="0.001" step="0.001" value="1" required></label><div class="production-components"><label>Hammadde 1<select name="component_product_id[]"><option value="0">Seçin</option><?php foreach($products as $p): ?><option value="<?= (int)$p['id'] ?>"><?= kd_e($p['name']) ?></option><?php endforeach; ?></select></label><label>Miktar<input type="number" name="quantity_per_batch[]" min="0.001" step="0.001"></label><label>Hammadde 2<select name="component_product_id[]"><option value="0">Seçin</option><?php foreach($products as $p): ?><option value="<?= (int)$p['id'] ?>"><?= kd_e($p['name']) ?></option><?php endforeach; ?></select></label><label>Miktar<input type="number" name="quantity_per_batch[]" min="0.001" step="0.001"></label><label>Hammadde 3<select name="component_product_id[]"><option value="0">Seçin</option><?php foreach($products as $p): ?><option value="<?= (int)$p['id'] ?>"><?= kd_e($p['name']) ?></option><?php endforeach; ?></select></label><label>Miktar<input type="number" name="quantity_per_batch[]" min="0.001" step="0.001"></label></div><label>Not<input name="notes"></label><button class="btn primary">Reçete oluştur</button></form></section>
<section class="panel customer-form-panel"><h3>Üretim emri oluştur</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="order"><label>Reçete<select name="recipe_id" required><?php foreach($recipes as $r): ?><option value="<?= (int)$r['id'] ?>"><?= kd_e($r['name']) ?> · <?= kd_e($r['output_name']) ?></option><?php endforeach; ?></select></label><label>Üretilecek miktar<input type="number" name="output_quantity" min="0.001" step="0.001" value="1" required></label><label>Planlanan tarih<input type="date" name="planned_at" value="<?= date('Y-m-d') ?>"></label><label>Not<input name="notes"></label><button class="btn secondary">Üretim emri aç</button></form></section></div>
<section class="panel customer-list-panel"><h3>Üretim emirleri</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Emir</th><th>Reçete</th><th>Çıktı ürünü</th><th>Miktar</th><th>Planlanan</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?= kd_e($o['order_number']) ?></td><td><?= kd_e($o['recipe_name']) ?></td><td><?= kd_e($o['output_name']) ?></td><td><?= number_format((float)$o['output_quantity'],3,',','.') ?></td><td><?= kd_e($o['planned_at']??'—') ?></td><td><?= kd_e($o['status']) ?></td><td><?php if($o['status']==='planned'): ?><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="complete"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><button class="btn primary">Üretimi tamamla</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="7">Üretim emri yok.</td></tr><?php endif; ?></tbody></table></div></section>
